// UpdateQuoteOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateQuoteOutputOnly(in *salespbv1.Quote, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "venues", "quotes"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLQuoteRepository{Svc: b.svc}
	patch := quoteToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "aperio.sales.v1/Quote", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getQuote)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Sales.Quotes.UpdateIfMatch(ctx, id, patch, quotesql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Sales.Quotes.UpdateOp(id, patch, new(quotesql.UpdateSalesQuotesByIdResponse)))
		return nil, nil
	})
}

